const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || '').trim();
const sessionId = body.sessionId || 'session-' + Date.now();
const userName = body.userName || 'Melómano';
const userPreferences = Array.isArray(body.preferences) ? body.preferences.join(', ') : 'Música en general';
const language = body.language || 'es';
const langNames = { es: 'Español', en: 'English', zh: '中文', fr: 'Français', it: 'Italiano', ja: '日本語' };
const languageName = langNames[language] || 'Español';

return [
  {
    json: {
      message,
      sessionId,
      userName,
      userPreferences,
      language,
      languageName,
      timestamp: new Date().toISOString()
    }
  }
];

